package run.ikaros.notes; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/private-notes/vaults/{vaultId}") public class PrivateVaultSecurityController{private final PrivateVaultSecurityService service;public PrivateVaultSecurityController(PrivateVaultSecurityService s){service=s;}@PostMapping("/actions/rotate-recovery-key")public Mono<VaultView> rotate(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID vaultId,@Valid@RequestBody UpdateRecoveryKeyRequest r){return service.rotateRecoveryKey(a,vaultId,r);}@GetMapping("/export")public Mono<PrivateVaultExport> export(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID vaultId){return service.export(a,vaultId);}}
